function CmsListViewModel() {
    "use strict";
    var self = this;

    self.searchText = ko.observable(document.getElementById("search-text").value).extend({ rateLimit: { timeout: 500, method: "notifyWhenChangesStop" } });

    self.searchText.subscribe(function() {
        doSearch();
    });
    

    function navigate(sortColumn, direction, search) {
        var query = "?";
        if (search) {
            query += "search=" + search + "&";
        }
        if (sortColumn) {
            query += "sortColumn=" + sortColumn + "&";
        }
        if (sortColumn) {
            query += "direction=" + direction + "&";
        }
        query = query.slice(0, -1);

        var newUrl = window.location.href.split('?')[0] + query;
        window.location = newUrl;
    }
    function doSearch() {
        var sortElement = document.querySelector("[data-column-sort='Ascending']") ||
            document.querySelector("[data-column-sort='Descending']");

        if (sortElement) {
            navigate(sortElement.getAttribute("data-column-index"),
                sortElement.getAttribute("data-column-sort"),
                document.getElementById("search-text").value);
        } else {
            navigate(null, null, document.getElementById("search-text").value);
        }
    }


    document.addEventListener('click',
        function (event) {
            //Delete modal hookup
            if (event.target.matches('[data-target="#deleteModal"]') ||
                event.target.parentElement.matches('[data-target="#deleteModal"]')) {
                var id = event.target.getAttribute("data-id") || event.target.parentElement.getAttribute("data-id");
                var title = event.target.getAttribute("data-title") || event.target.parentElement.getAttribute("data-title");

                document.getElementById("item-title").innerText = title;

                var removeForm = document.getElementById("remove-form");
                removeForm.action = removeForm.getAttribute("data-action") + id;
            }
            //Sort order hookup
            else if (event.target.matches('[data-sort]')) {
                var index = event.target.getAttribute("data-column-index");
                var direction = event.target.getAttribute("data-column-sort");

                if (direction === "Descending" || direction === "Unsorted") {
                    direction = "Ascending";
                } else {
                    direction = "Descending";
                }

                navigate(index, direction, document.getElementById("search-text").value);
            }
            //Search button hookup
            else if (event.target.matches('#input-search') ||
                event.target.parentElement.matches('#input-search')) {
                doSearch();
            }
        },
        false);
}
function NavBarLinkViewModel(data) {
    "use strict";
    var self = this;

    var original = "";
    self.editing = ko.observable(false);

    self.id = ko.observable(data.id);
    self.key = ko.observable(data.key);
    self.text = ko.observable(data.text);
    self.order = ko.observable(data.order);
    self.enabled = ko.observable(data.enabled);

    self.edit = function () {
        original = self.text();
        self.editing(true);
    };

    self.cancelEdit = function () {
        self.text(original);
        original = "";
        self.editing(false);
    };

    self.saveEdit = function () {
        if (self.text() === "") {
            self.text(original);
            original = "";
        }
        self.editing(false);
    };

    self.getJson = function() {
        return {
            id: self.id(),
            key: self.key(),
            text: self.text(),
            order: self.order(),
            enabled: self.enabled()
        };
    };
}

function FeaturesViewModel(links) {
    "use strict";
    var self = this;

    self.links = ko.observableArray([]);

    self.orderedLinks = ko.pureComputed(function() {
        return _.sortBy(self.links(), function (item) {
            return item.order();
        });
    });

    for (var i = 0; i < links.length; i++) {
        self.links.push(new NavBarLinkViewModel(links[i]));
    }

    self.discard = function () {
        window.location.reload();
    };

    self.saveChanges = function () {
        var featuresData = {
            links: [],
            __RequestVerificationToken: document.getElementsByName("__RequestVerificationToken")[0].value
        };

        for (var i = 0; i < self.orderedLinks().length; i++) {
            featuresData.links.push(self.orderedLinks()[i].getJson());
        }

        ajax.post("/Settings/Features/Update", featuresData).done(function() {
            window.location.reload();
        });
    };

    self.canMoveUp = function (item) {
        return item && item.order() > 0;
    };

    self.canMoveDown = function (item) {
        return item && item.order() < self.links().length - 1;
    };

    function findItemAtPositon(position) {
        for (var i = 0; i < self.links().length; i++) {
            if (self.links()[i].order() === position) {
                return self.links()[i];
            }
        }
        return undefined;
    }

    function moveToPosition(itemToMove, position) {
        var itemToSwap = findItemAtPositon(position);
        itemToSwap.order(itemToMove.order());
        itemToMove.order(position);

        self.links.sort(function(i1, i2) {
            if (i1 > i2) {
                return 1;
            } else {
                return -1;
            }
        });
    }

    self.moveUp = function(item) {
        if (self.canMoveUp(item)) {
            moveToPosition(item, item.order() - 1);
        }
    };

    self.moveDown = function (item) {
        if (self.canMoveDown(item)) {
            moveToPosition(item, item.order() + 1);
        }
    };


}
function MerchCategoryViewModel(data) {
    "use strict";
    var self = this;

    function findItemAtPositon(position) {
        for (var i = 0; i < self.subcategoryTypes().length; i++) {
            if (self.subcategoryTypes()[i].order() === position) {
                return self.subcategoryTypes()[i];
            }
        }
        return undefined;
    }

    function moveToPosition(itemToMove, position) {
        var itemToSwap = findItemAtPositon(position);
        itemToSwap.order(itemToMove.order());
        itemToMove.order(position);

        self.subcategoryTypes.sort(function (i1, i2) {
            if (i1 > i2) {
                return 1;
            } else {
                return -1;
            }
        });
    }

    self.name = ko.observable(data.name);
    self.order = ko.observable(data.order);

    self.addName = ko.observable("");

    if (data.subcategoryTypes) {
        self.subcategoryTypes = ko.observableArray([]);

        for (var i = 0; i < data.subcategoryTypes.length; i++) {
            self.subcategoryTypes.push(new MerchCategoryViewModel(data.subcategoryTypes[i]));
        }

        self.orderedSubcategories = ko.pureComputed(function () {
            return _.sortBy(self.subcategoryTypes(), function (item) {
                return item.order();
            });
        });

        self.add = function () {
            if (self.addName().trim() === "") {
                return;
            }

            var newItem = {
                name: self.addName(),
                order: self.subcategoryTypes().length
            };
            self.subcategoryTypes.push(new MerchCategoryViewModel(newItem));
            self.addName("");
        };

        self.canMoveUp = function (item) {
            return item && item.order() > 0;
        };

        self.canMoveDown = function (item) {
            return item && item.order() < self.subcategoryTypes().length - 1;
        };

        self.moveUp = function (item) {
            if (self.canMoveUp(item)) {
                moveToPosition(item, item.order() - 1);
            }
        };

        self.moveDown = function (item) {
            if (self.canMoveDown(item)) {
                moveToPosition(item, item.order() + 1);
            }
        };

        self.remove = function (itemToRemove) {
            ajax.get("/Settings/Types/AllowDeleteMerchSubcategoryType", itemToRemove.getJson()).done(function (result) {
                if (result.canRemove) {
                    var order = itemToRemove.order();
                    self.subcategoryTypes.remove(itemToRemove);

                    var itemsToUpdate = _.filter(self.subcategoryTypes(),
                        function (item) {
                            return item.order() > order;
                        });

                    _.each(itemsToUpdate,
                        function (item) {
                            item.order(item.order() - 1);
                        });
                } else {
                    messages.danger("Cannot remove '" +
                        itemToRemove.name() +
                        "' because it has merch assigned to it. Move all merch to a different subcategory before removing");
                }
            });

        };
    }

    self.getJson = function () {
        var json = {
            name: self.name(),
            order: self.order()
        };
        if (self.subcategoryTypes) {
            json.subcategoryTypes = [];
            for (var j = 0; j < self.orderedSubcategories().length; j++) {
                json.subcategoryTypes.push(self.subcategoryTypes()[j].getJson());
            }
        }

        return json;
    };
}

