function ListInputItemMetaDataViewModel(listName, index, name, value) {
    "use strict";
    var self = this;

    self.name = ko.pureComputed(function () {
        return listName + "[" + index() + "]." + name[0].toUpperCase() + name.slice(1);
    });
    self.value = value;
}

function ListInputItemViewModel(listName, item, index, parent, singularObjectName) {
    "use strict";
    var self = this;
    self.index = ko.observable(index);
    self.properties = ko.observableArray([]);
    self.propertyNames = [];
    for (var propertyName in item) {
        if (item.hasOwnProperty(propertyName)) {
            self.propertyNames.push(propertyName);
            self[propertyName] = ko.observable(item[propertyName] || "");
            if (item[propertyName] === 0) {
                self[propertyName](0);
            }
            self.properties.push(new ListInputItemMetaDataViewModel(listName, self.index, propertyName, self[propertyName]));
        }
    }

    self.showEditItem = function () {
        parent.isEdit(true);
        parent.templateHeaderText("Edit " + singularObjectName);

        for (var i = 0; i < self.propertyNames.length; i++) {
            var propertyName = self.propertyNames[i];
            self[propertyName + "Temp"] = self[propertyName]();
        }
        parent.selectedItem(self);
    };

    self.revert = function () {
        for (var i = 0; i < self.propertyNames.length; i++) {
            var propertyName = self.propertyNames[i];
            self[propertyName](self[propertyName + "Temp"]);
        }
    };
}

function ListInputViewModel(listMemberName, items, template, formTemplate, nameField, objectName, validators, isOrdered, orderPropertyName) {
    "use strict";
    var self = this;

    var objectTemplate = template;
    var nameProperty = nameField;
    var singularObjectName = objectName;
    var ordered = isOrdered;
    var orderProperty = orderPropertyName;

    self.validators = validators;

    self.listMemberName = listMemberName;
    self.items = ko.observableArray([]);

    self.selectedItem = ko.observable();
    self.template = ko.observable(formTemplate);

    if (items) {
        for (var i = 0; i < items.length; i++) {
            self.items.push(new ListInputItemViewModel(self.listMemberName, items[i], i, self, singularObjectName));
        }
    }

    self.itemToDeleteName = ko.pureComputed(function () {
        return self.selectedItem()[nameProperty]();
    });

    self.templateHeaderText = ko.observable();

    self.showAddItem = function () {
        self.templateHeaderText("Add " + singularObjectName);
        self.selectedItem(new ListInputItemViewModel(self.listMemberName, objectTemplate, self.items().length, self));
    };

    self.showRemoveItem = function (item) {
        self.templateHeaderText("Remove " + singularObjectName);
        self.selectedItem(item);
    };

    self.isEdit = ko.observable(false);

    self.removeItem = function () {
        self.items.remove(self.selectedItem());
        for (var j = 0; j < self.items().length; j++) {
            self.items()[j].index(j);
        }
    };

    function validateSelectedItem() {
        var isValid = true;
        for (var j = 0; j < self.selectedItem().propertyNames.length; j++) {
            var propertyName = self.selectedItem().propertyNames[j];
            var property = self.selectedItem()[propertyName];

            var validator = _.find(validators, { name: propertyName });
            if (validator) {
                validation.remove(validator.id);
                if (validator.isRequired && (property() === null || (typeof property() === "string" && property().trim() === ""))) {
                    validation.invalid(validator.id, validator.displayName + (validator.isPlural ? " are required" : " is required"));
                    isValid = false;
                }
                else if (validator.validateUrl && property() !== null) {
                    if (property().startsWith("mailto:")) {
                        var email = property().replace("mailto:", "");
                        if (/^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/.test(email) === false) {
                            validation.invalid(validator.id, validator.displayName + " is not a valid Email Address");
                            isValid = false;
                        }
                    } else {
                        if (/https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/.test(property()) === false) {
                            validation.invalid(validator.id, validator.displayName + " is not a valid Url");
                            isValid = false;
                        }
                    }
                }
            }
        }
        return isValid;
    }

    if (ordered) {
        function findItemAtPositon(position) {
            for (var i = 0; i < self.items().length; i++) {
                if (self.items()[i][orderProperty]() === position) {
                    return self.items()[i];
                }
            }
            return undefined;
        }

        function moveToPosition(itemToMove, position) {
            var itemToSwap = findItemAtPositon(position);
            itemToSwap[orderProperty](itemToMove[orderProperty]());
            itemToMove[orderProperty](position);

            self.items.sort(function (i1, i2) {
                if (i1 > i2) {
                    return 1;
                } else {
                    return -1;
                }
            });
        }

        self.orderedItems = ko.pureComputed(function () {
            return _.sortBy(self.items(), function (item) {
                return item[orderProperty]();
            });
        });

        self.canMoveUp = function (item) {
            return item && item[orderProperty]() > 0;
        };

        self.canMoveDown = function (item) {
            return item && item[orderProperty]() < self.orderedItems().length - 1;
        };

        self.moveUp = function (item) {
            if (self.canMoveUp(item)) {
                moveToPosition(item, item[orderProperty]() - 1);
            }
        };

        self.moveDown = function (item) {
            if (self.canMoveDown(item)) {
                moveToPosition(item, item[orderProperty]() + 1);
            }
        };
    }

    self.saveItem = function () {
        if (validateSelectedItem()) {
            if (self.isEdit()) {
                self.isEdit(false);
                $('#addEditModal' + listMemberName).modal('hide');
            } else {
                self.items.push(self.selectedItem());
                $('#addEditModal' + listMemberName).modal('hide');
            }
        }
    };

    $('#addEditModal' + listMemberName).on('hidden.bs.modal', function () {
        if (self.isEdit()) {
            self.selectedItem().revert();
            self.isEdit(false);
        }
    });

    ko.applyBindings(self, $("#addEditModal" + listMemberName)[0]);
    ko.applyBindings(self, $("#deleteModal" + listMemberName)[0]);
}
function NestedSelectListViewModel(values, selectedItem, selectedChildItem) {
    "use strict";
    var self = this;

    self.options = ko.observableArray(values);
    self.childOptions = ko.observableArray([]);
    self.selectedOption = ko.observable(selectedItem || values[0].value);
    self.selectedChildOption = ko.observable(selectedChildItem || values[0].children[0].value);

    function setChildOptions() {
        for (var i = 0; i < self.options().length; i++) {
            var option = self.options()[i];
            if (option.value === self.selectedOption()) {
                self.childOptions(option.children);
                return;
            }
        }
        self.childOptions([]);
    }

    setChildOptions();

    self.selectedOption.subscribe(function() {
        setChildOptions();
    });
}
function PhotoMetaDataViewModel(listName, index, name, value) {
    "use strict";
    var self = this;

    self.name = ko.pureComputed(function () {
        return listName + "[" + index() + "]." + name[0].toUpperCase() + name.slice(1);
    });
    self.value = value;
}

function PhotoViewModel(listName, item, index, imagePathName, parent) {
    "use strict";
    var self = this;
    self.index = ko.observable(index);
    self.properties = ko.observableArray([]);
    self.propertyNames = [];
    for (var propertyName in item) {
        if (item.hasOwnProperty(propertyName)) {
            self.propertyNames.push(propertyName);
            self[propertyName] = ko.observable(item[propertyName] || "");
            if (propertyName !== "blob") {
                self.properties.push(new PhotoMetaDataViewModel(listName, self.index, propertyName, self[propertyName]));
            }
        }
    }
    if (!self.blob) {
        self.blob = ko.observable(null);
    }

    self.image = ko.pureComputed(function () {
        return self.blob() || self[imagePathName]();
    });

    self.hasImage = ko.pureComputed(function () {
        return self.blob() !== null || (self[imagePathName]() !== null && self[imagePathName]() !== "");
    });

    self.hasAddedFile = ko.pureComputed(function () {
        return self.blob() !== null;
    });
}

function PhotoGalleryViewModel(listMemberName, items, imagePathName, allowedTypes, template) {
    "use strict";
    var self = this;

    var objectTemplate = template;

    self.listMemberName = listMemberName;
    self.items = ko.observableArray([]);
    self.files = ko.observable(null);

    if (items) {
        for (var i = 0; i < items.length; i++) {
            self.items.push(new PhotoViewModel(self.listMemberName, items[i], i, imagePathName, self));
        }
    }

    self.addedFiles = ko.observableArray([]);

    function readBlob(file) {
        var reader = new FileReader();
        reader.onload = function (e) {
            objectTemplate.blob = e.target.result;
            var index = self.items().length;
            self.addedFiles.push(self.listMemberName + "_" + index);
            self.items.push(new PhotoViewModel(self.listMemberName, objectTemplate, index, imagePathName, self));
        };
        reader.readAsDataURL(file);
    }

    self.removedFiles = ko.observableArray([]);
    self.removeFile = function (item) {
        if (item.imagePath()) {
            self.removedFiles.push(item.imagePath());
        } else {
            self.addedFiles.remove(self.listMemberName + "_" + item.index());
            self.addedFiles.valueHasMutated();
        }
        self.items.remove(item);
        for (var j = 0; j < self.items().length; j++) {
            var currentIndex = self.items()[j].index();
            var addedFilesIndex = self.addedFiles.indexOf(self.listMemberName + "_" + currentIndex);
            if (addedFilesIndex > -1) {
                self.addedFiles()[addedFilesIndex] = self.listMemberName + "_" + j;
                self.addedFiles.valueHasMutated();
            }
            self.items()[j].index(j);
        }
    };

    self.files.subscribe(function (files) {
        if (files) {
            for (var j = 0; j < files.length; j++) {
                var file = files[j];

                if (allowedTypes.includes(file.type)) {
                    readBlob(file);
                }
            }
        }
    });
}
function YouTubeViewModel(id) {
    "use strict";
    var self = this;

    self.youTubeId = ko.observable(id);

    self.youTubeUrl = ko.pureComputed({
        read: function() {
            return self.youTubeId() ? "https://www.youtube.com/watch?v=" + self.youTubeId() : null;
        },
        write: function(url) {
            var match = url.match(/^.*(?:(?:youtu\.be\/|v\/|vi\/|u\/\w\/|embed\/)|(?:(?:watch)?\?v(?:i)?=|\&v(?:i)?=))([^#\&\?]*).*/);
            if (match && match[1]) {
                self.youTubeId(match[1]);
            } else {
                self.youTubeId(null);
            }

        },
        owner: self
    });

    self.hasId = ko.pureComputed(function() {
        return self.youTubeId() !== null && self.youTubeId() !== null && self.youTubeId() !== "";
    });

    self.thumbnail = ko.pureComputed(function() {
        if (self.hasId()) {
            return "https://img.youtube.com/vi/" + self.youTubeId() + "/0.jpg";
        }
        return "";
    });
}
// ReSharper disable InconsistentNaming
typeof tinymce !== 'undefined' && tinymce.PluginManager.add('imageUpload', function (editor) {
    var uploading = false;

    function showUploadingUI() {
        uploading = true;
        $("#tinymce-image-upload-form").hide();
        $("#tinymce-image-upload-uploading").show();
    }

    function hideUploadingUI() {
        uploading = false;
        $("#tinymce-image-upload-form").show();
        $("#tinymce-image-upload-uploading").hide();
    }

    function openDialog() {
        $("#tinymce-image-upload-uploading").hide();
        $("#tinymce-image-upload-form").off("submit");
        $("#tinymce-image-upload").modal("show");

        $("#tinymce-image-upload").off("hide.bs.modal");
        $("#tinymce-image-upload").off("hidden.bs.modal");
        $('#tinymce-image-upload').on('hide.bs.modal', function (e) {
            if (uploading) {
                e.preventDefault();
                e.stopImmediatePropagation();
                return false;
            }
        });
        $('#tinymce-image-upload').on('hidden.bs.modal', function (e) {
            document.getElementById("tinymce-image-upload-file").value = null;
            hideUploadingUI();
        });


        $("#tinymce-image-upload-form").on("submit", function (e) {
            e.preventDefault();
            e.stopImmediatePropagation();
            var files = document.getElementById("tinymce-image-upload-file").files;
            showUploadingUI();

            ajax.postWithFiles("/Uploads/UploadRichTextImage", files).done(function (response) {
                if (response.url) {
                    var img = "<img src=\"" + response.url + "\" width=\"100%\">";
                    editor.insertContent(img);
                    hideUploadingUI();
                    uploading = false;
                    $("#tinymce-image-upload").modal("hide");
                    document.getElementById("tinymce-image-upload-file").value = null;
                } else {
                    alert(response.error);
                    hideUploadingUI();
                    uploading = false;
                }
            });
        });
    }

    editor.ui.registry.addButton('imageUpload', {
        tooltip: 'Add Image',
        icon: 'image',
        onAction: function () {
            // Open window
            openDialog();
        }
    });
});

// ReSharper disable InconsistentNaming
typeof tinymce !== 'undefined' && tinymce.PluginManager.add('youtube', function (editor) {
    var uploading = false;

    function openDialog() {
        $("#tinymce-youtube-form").off("submit");
        $("#tinymce-youtube").modal("show");

        $("#tinymce-youtube").off("hide.bs.modal");
        $("#tinymce-youtube").off("hidden.bs.modal");
        $('#tinymce-youtube').on('hide.bs.modal', function (e) {
            if (uploading) {
                e.preventDefault();
                e.stopImmediatePropagation();
                return false;
            }
        });
        $('#tinymce-youtube').on('hidden.bs.modal', function (e) {
            document.getElementById("tinymce-youtube-url").value = null;
        });


        $("#tinymce-youtube-form").on("submit", function (e) {
            e.preventDefault();
            e.stopImmediatePropagation();
            var url = document.getElementById("tinymce-youtube-url").value;
            var slug = "";
            var match = url.match(/^.*(?:(?:youtu\.be\/|v\/|vi\/|u\/\w\/|embed\/)|(?:(?:watch)?\?v(?:i)?=|\&v(?:i)?=))([^#\&\?]*).*/);
            if (match && match[1]) {
                slug = match[1];
            } else {
                alert("YouTube Url not valid");
                return;
            }

            var img = "<p><div class=\"video-wrapper\"><iframe allowfullscreen=\"allowfullscreen\" src=\"https://www.youtube.com/embed/" + slug + "?enablejsapi=1&amp;version=3&amp;playerapiid=ytplayer\"></iframe></div><p>";
            editor.insertContent(img);
            uploading = false;
            $("#tinymce-youtube").modal("hide");
        });
    }

    editor.ui.registry.addButton('youTube', {
        tooltip: 'Embed Youtube Video',
        icon: 'embed',
        onAction: function () {
            // Open window
            openDialog();
        }
    });
});
